WITH ranked AS (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r
  FROM employees WHERE salary IS NOT NULL
)
SELECT DISTINCT salary FROM ranked WHERE r = 2;

-- Follow-up: one value per department; departments with <2 values are absent.
WITH ranked AS (
  SELECT department_id, salary,
         DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS r
  FROM employees WHERE salary IS NOT NULL
)
SELECT DISTINCT department_id, salary FROM ranked WHERE r = 2;

SELECT MAX(salary) AS second_salary
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);
